const app = document.querySelector('#app');
const api = (path, options={}) => fetch(`/api${path}`, {headers:{'Content-Type':'application/json'}, ...options}).then(async r => {const data=await r.json(); if(!r.ok){const detail=Array.isArray(data.detail)?data.detail.map(x=>x.msg||String(x)).join('；'):data.detail;throw new Error(detail||'操作失败')} return data;});
