function escape(s=''){return String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[x]));}
function lineupName(p){const name=String(p.name||p.name_zh||'').trim();const parts=name.split(/\s+/).filter(Boolean);return parts.length<2?name:`${parts[0][0]} ${parts.slice(1).join(' ')}`;}
function avatarMedia(p){return p.avatar_url?`<span class="avatar-placeholder" aria-hidden="true"></span><img src="${escape(p.avatar_url)}" alt="" onload="this.parentElement.classList.add('has-image')" onerror="this.remove()">`:`<span class="avatar-placeholder" aria-hidden="true"></span>`}
function clubMark(c){return `<div class="club-mark">${c.logo_url?`<img src="${escape(c.logo_url)}" alt="${escape(c.name)} 队标" onerror="this.remove()">`:''}<span class="club-mark-fallback" aria-hidden="true"></span></div>`}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2400)}
function scoutBadge(p){return p.scout_rating!=null?`<span class="scout-badge" title="基于 ${p.scout_report_count||0} 份球探报告的平均分">球探 ${p.scout_rating}</span>`:`<span class="scout-pending">待球探</span>`}
function playerCard(p){return `<article class="card player-card" onclick="location.hash='#/players/${p.id}'"><div class="player-top"><div class="avatar">${avatarMedia(p)}</div><div><div class="name">${escape(p.name)}</div><div class="sub">${escape(p.club_name||'')}</div></div><span class="rating">OVR ${p.overall}</span></div><div class="meta"><span class="pill">${posLabel[p.position]||p.position}</span><span>${p.age} 岁</span><span>${escape(p.nationality||'')}</span></div></article>`}
function featuredPlayerCard(p){return `<article class="card player-card featured-player" onclick="location.hash='#/players/${p.id}'"><div class="player-top"><div class="avatar">${avatarMedia(p)}</div><div><div class="name">${escape(p.name)}</div><div class="sub">${escape(p.club_name||'')}</div></div><span class="rating">OVR ${p.overall}</span></div><div class="meta"><span class="pill">${posLabel[p.position]||p.position}</span><span>本赛季 ${p.recent_goals} 球${p.recent_assists?` · ${p.recent_assists} 助攻`:''}</span></div></article>`}
function loadCore(){return Promise.all([api('/players'),api('/clubs'),api('/featured-players')]).then(([p,c,f])=>{players=p;clubs=c;featuredPlayers=f;});}
function nav(){const route=location.hash.slice(1)||'/discover'; if(route==='/discover') discover(); else if(route==='/players'||route.startsWith('/players?')) playersPage(); else if(route==='/clubs') clubsPage(); else if(route.startsWith('/squad-query')) squadQuery(); else if(route.startsWith('/clubs/')) clubDetail(route.split('/')[2]); else if(route==='/lineups') lineupsPage(); else if(route.startsWith('/lineups/new')) lineupEditor(); else if(route.startsWith('/lineups/')) lineupEditor(Number(route.split('/')[2])); else if(route==='/favorites') favoritesPage(); else if(route==='/sync') syncPage(); else if(route.startsWith('/players/')) playerDetail(route.split('/')[2]); else discover();}
function discover(){const featured=featuredPlayers.slice(0,12);app.innerHTML=`<section class="hero"><div class="eyebrow">ScoutXI · 足球球探与阵容管理</div><h1>把观察，变成一套能复用的阵容判断。</h1><p>探索五大联赛与知名联赛球员库，查看俱乐部阵容，创建你的战术方案，并记录球探观察。</p><form class="searchbar" onsubmit="event.preventDefault(); location.hash='#/players?search='+encodeURIComponent(this.q.value)"><input name="q" placeholder="搜索球员或俱乐部，例如梅西、C 罗、曼城"><button>开始发现</button></form></section><section class="section"><div class="section-head"><div><h2>近期焦点球员</h2><p>按五大联赛本赛季进球、助攻排序；仅展示有数据依据的球员。</p></div><a class="link" href="#/players">查看全部 →</a></div><div class="grid">${featured.length?featured.map(featuredPlayerCard).join(''):`<div class="empty">正在等待联赛表现数据刷新。</div>`}</div></section><section class="section"><div class="section-head"><div><h2>热门俱乐部</h2><p>浏览当前阵容与远程队标</p></div></div><div class="grid">${clubs.map(c=>`<article class="card club-card" onclick="location.hash='#/clubs/${c.id}'">${clubMark(c)}<div class="name">${c.name}</div><div class="sub">${c.league} · ${c.country} · ${c.player_count} 名球员</div></article>`).join('')}</div></section>`;}
function playersPage(){const search=new URLSearchParams(location.hash.split('?')[1]||'').get('search')||'';app.innerHTML=`<div class="eyebrow">球员发现</div><h1 class="page-title">发现目标球员</h1><p class="muted">支持中英文姓名、俱乐部、位置与年龄条件的本地搜索。</p><form class="filters" id="filters"><input id="q" value="${escape(search)}" placeholder="姓名或俱乐部"><select id="position"><option value="">所有位置</option>${Object.entries(posLabel).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><select id="club"><option value="">所有俱乐部</option>${clubs.map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select><input id="ageMin" type="number" min="15" max="45" placeholder="最小年龄"><input id="ageMax" type="number" min="15" max="45" placeholder="最大年龄"><button>筛选</button></form><div id="results" class="grid"></div>`;document.querySelector('#filters').onsubmit=e=>{e.preventDefault();const f=e.target;const params=new URLSearchParams();if(f.q.value.trim())params.set('q',f.q.value.trim());if(f.position.value)params.set('position',f.position.value);if(f.club.value)params.set('club_id',f.club.value);if(f.ageMin.value)params.set('age_min',f.ageMin.value);if(f.ageMax.value)params.set('age_max',f.ageMax.value);api(`/players?${params}`).then(renderResults).catch(err=>{document.querySelector('#results').innerHTML=`<div class="empty">${escape(err.message)}</div>`;toast(err.message)});};document.querySelector('#filters').dispatchEvent(new Event('submit',{cancelable:true}));}
function renderResults(items){document.querySelector('#results').innerHTML=items.length?items.map(playerCard).join(''):`<div class="empty">没有匹配球员。请试试更宽松的筛选条件。</div>`;}
function playerDetail(id){api(`/players/${id}`).then(p=>{selectedPlayer=p;app.innerHTML=`<a class="link" href="#/players">← 返回球员发现</a><section class="detail-head section"><div class="avatar big">${avatarMedia(p)}</div><div><div class="eyebrow">${p.club_name} · ${p.league}</div><h1>${escape(p.name)}</h1><div class="sub">${posLabel[p.position]} · ${p.age} 岁 · ${p.nationality} · ${p.foot}脚 · ${p.scout_rating!=null?`球探评分 ${p.scout_rating}/10（${p.scout_report_count} 份报告）`:'待球探报告'}</div></div><div class="actions"><button class="secondary" onclick="toggleFav('${p.id}',${!p.favorite})">${p.favorite?'★ 已收藏':'☆ 收藏'}</button><button onclick="location.hash='#/lineups/new?player=${p.id}'">加入阵容</button></div></section><div class="detail-grid"><div><section class="card"><h2>球员概览</h2><p class="muted">${escape(p.bio)}</p><div class="stat-row"><div class="stat"><b>${p.appearances}</b><small>出场</small></div><div class="stat"><b>${p.goals}</b><small>进球</small></div><div class="stat"><b>${p.assists}</b><small>助攻</small></div><div class="stat"><b>${p.scout_rating??'—'}</b><small>球探评分</small></div></div><div class="source">评分为保存的球探报告平均值，不是外部能力值或 AI 推断。数据来源：${escape(p.data_source||'本地演示数据')} · 最后同步：${escape(p.source_updated_at||'尚未同步')}</div></section><section class="card section"><h2>球探报告</h2><div id="reports">${p.reports.length?p.reports.map(reportHtml).join(''):`<p class="muted">暂无球探报告。写下第一条观察吧。</p>`}</div></section></div><aside class="card"><h2>新增球探报告</h2><p class="note">评分和主观观察分开保存，不生成 AI 结论。</p><form id="report-form" class="form-grid"><label>技术<input name="technical" type="number" min="1" max="10" value="7"></label><label>战术<input name="tactical" type="number" min="1" max="10" value="7"></label><label>身体<input name="physical" type="number" min="1" max="10" value="7"></label><label>心理<input name="mental" type="number" min="1" max="10" value="7"></label><label class="wide">优点<input name="strengths" required placeholder="例如：转身快、传球选择稳健"></label><label class="wide">风险<input name="risks" required placeholder="例如：高压下处理球待观察"></label><label>标签<input name="tags" placeholder="组织, 左脚"></label><label>推荐等级<select name="recommendation"><option>重点关注</option><option>持续观察</option><option>不建议</option></select></label><label>观察日期<input name="observed_at" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label class="wide">观察笔记<textarea name="notes" rows="5" required placeholder="记录比赛背景、具体表现和结论依据"></textarea></label><button class="wide">保存报告</button></form></aside></div>`;document.querySelector('#report-form').onsubmit=e=>saveReport(e,p.id);});}
function reportHtml(r){return `<article class="report"><div><span class="pill">${r.recommendation}</span> <span class="sub">观察于 ${r.observed_at}</span></div><div class="report-grid">${[['技术',r.technical],['战术',r.tactical],['身体',r.physical],['心理',r.mental]].map(x=>`<div class="score"><b>${x[1]}</b>${x[0]}</div>`).join('')}</div><div><b>优点：</b>${escape(r.strengths)}</div><div><b>风险：</b>${escape(r.risks)}</div><p class="muted">${escape(r.notes)}</p><div class="sub">标签：${escape(r.tags||'无')}</div></article>`;}
function saveReport(e,id){e.preventDefault();const o=Object.fromEntries(new FormData(e.target));['technical','tactical','physical','mental'].forEach(k=>o[k]=+o[k]);api(`/players/${id}/reports`,{method:'POST',body:JSON.stringify(o)}).then(()=>{toast('球探报告已保存');playerDetail(id)}).catch(err=>toast(err.message));}
function toggleFav(id,favorite){api(`/players/${id}/favorite`,{method:'PUT',body:JSON.stringify({favorite})}).then(()=>{toast(favorite?'已加入收藏':'已移出收藏');playerDetail(id)});}
function clubsPage(){app.innerHTML=`<div class="eyebrow">俱乐部</div><h1 class="page-title">俱乐部阵容</h1><p class="muted">选择俱乐部，查看当前可用阵容。</p><section class="grid section">${clubs.map(c=>`<article class="card club-card" onclick="location.hash='#/clubs/${c.id}'">${clubMark(c)}<div class="name">${c.name}</div><div class="sub">${c.league} · ${c.country}</div><div class="meta"><span class="pill">${c.player_count} 名球员</span></div></article>`).join('')}</section>`;}
function clubDetail(id){api(`/clubs/${id}`).then(data=>{const c=data.club;const time=data.synced_at?data.synced_at.replace('T',' ').replace('Z',' UTC'):'尚未同步';app.innerHTML=`<a class="link" href="#/clubs">← 返回俱乐部</a><section class="detail-head section">${clubMark(c)}<div><div class="eyebrow">${c.country} · ${c.league}</div><h1>${c.name}</h1><div class="sub">${data.season} 阵容 · ${data.players.length} 名球员</div></div><div class="actions"><button class="secondary" onclick="location.hash='#/squad-query?club=${id}'">查询阵容</button><button onclick="location.hash='#/lineups/new?club=${id}'">用此阵容创建</button></div></section><div class="source section">来源：${data.source} · 最后同步：${time}</div><section class="section"><div class="section-head"><div><h2>当前阵容</h2><p>按综合能力值展示；点击球员查看能力档案或加入你的阵容。</p></div></div><div class="squad">${data.players.sort((a,b)=>b.overall-a.overall).map(p=>`<article class="squad-item" onclick="location.hash='#/players/${p.id}'"><div class="avatar">${avatarMedia(p)}</div><div><div class="name">${p.name} <span class="pill">${p.position}</span></div><div class="sub">OVR ${p.overall} · ${p.age||'?'} 岁 · ${p.ability_is_reference?'官方参考':'基准值'}</div></div></article>`).join('')}</div></section>`;});}
function lineupsPage(){api('/lineups').then(items=>{app.innerHTML=`<div class="section-head"><div><div class="eyebrow">我的阵容</div><h1 class="page-title">阵容方案</h1><p class="muted">保存后的坐标、首发、替补、队长和备注会存入本地 SQLite。</p></div><button onclick="location.hash='#/lineups/new'">+ 创建阵容</button></div><div class="lineup-list section">${items.length?items.map(x=>`<article class="card"><span class="pill">${x.formation}</span><h2>${escape(x.name)}</h2><p class="muted">${x.season} · ${x.player_count} 人 · 更新于 ${new Date(x.updated_at).toLocaleString('zh-CN')}</p><button onclick="location.hash='#/lineups/${x.id}'">打开编辑器</button></article>`).join(''):`<div class="empty">还没有阵容方案。创建第一个 4-3-3 或 4-2-3-1 吧。</div>`}</div>`;});}
function lineupEditor(id){const qs=new URLSearchParams(location.hash.split('?')[1]||'');const player=qs.get('player'),club=qs.get('club');const render=x=>{activeLineup=x||{name:club?`${clubs.find(c=>c.id===club)?.name||''} 战术方案`:'我的阵容',formation:'4-3-3',season:'2026/27',captain_id:null,notes:'',tactic_style:'均衡',mentality:'均衡',attacking_width:'标准',pressing:'中位',slots:[],source_club:club};if(player&&!activeLineup.slots.some(s=>s.player_id===player)){const p=players.find(p=>p.id===player);if(p) addPlayerToState(p.id);}renderEditor();};id?api(`/lineups/${id}`).then(render):render();}
function freeZoneFor(playerId){const p=players.find(x=>x.id===playerId);if(!p)return null;const free=formations[activeLineup.formation].filter(z=>!activeLineup.slots.some(s=>s.role==='STARTER'&&s.tactical_role===z.role));const preferred={GK:['GK'],LB:['LB','LWB'],CB:['LCB','CB','RCB'],RB:['RB','RWB'],DM:['DM','LDM','RDM','LCM','CM','RCM'],CM:['LCM','CM','RCM','LDM','RDM'],AM:['AM','LAM','RAM','LCM','CM','RCM'],LW:['LW','LM','LWB','LAM'],ST:['ST','LST','RST'],RW:['RW','RM','RWB','RAM']}[p.position]||[];const primary=free.find(z=>preferred.includes(z.role)&&z.allow.includes(p.position));if(primary)return primary;if(p.position==='GK')return null;return free.find(z=>z.role!=='GK'&&z.allow.includes(p.position))||null;}
function zoneByRole(role){return formations[activeLineup.formation].find(z=>z.role===role);}
function editorPlayers(){const selected=new Set(activeLineup.slots.map(s=>s.player_id));return (activeLineup.source_club?players.filter(p=>p.club_id===activeLineup.source_club):players).filter(p=>!selected.has(p.id));}
function renderEditor(){const lineup=activeLineup;app.innerHTML=`<div class="section-head"><div><div class="eyebrow">阵容编辑器</div><h1 class="page-title">${lineup.id?'编辑':'创建'}阵容</h1><p class="muted">首发必须放进匹配的位置框，GK 固定在球门一侧，ST 固定在前场。</p></div><a class="button secondary" href="#/lineups">返回列表</a></div><div class="lineup-layout section"><aside class="panel"><h3>阵容设置</h3><label class="note">阵容名称</label><input id="lineup-name" value="${escape(lineup.name)}" style="width:100%;margin:5px 0 12px"><label class="note">阵型</label><select id="formation" style="width:100%;margin:5px 0 12px">${Object.keys(formations).map(f=>`<option ${lineup.formation===f?'selected':''}>${f}</option>`).join('')}</select><label class="note">备注</label><textarea id="lineup-notes" rows="3" placeholder="战术思路、换人计划…">${escape(lineup.notes||'')}</textarea><h3 style="margin-top:20px">球员池</h3><p class="note">点击球员会放入第一个匹配的空位置；没有空位则进入替补席。</p><div class="pool">${editorPlayers().map(p=>`<div class="pool-player" onclick="addPlayer('${p.id}')"><b>${p.name}</b> <span class="pill">${p.position}</span><div class="sub">${p.club_name||clubs.find(c=>c.id===p.club_id)?.name||''} · ${p.age||'?'} 岁</div></div>`).join('')}</div></aside><section><div class="pitch-wrap"><div id="pitch" class="pitch">${formations[lineup.formation].map(zoneHtml).join('')}${lineup.slots.filter(s=>s.role==='STARTER').map(slotHtml).join('')}</div><div class="bench" id="bench" ondragover="event.preventDefault()" ondrop="dropOnBench(event)">${lineup.slots.filter(s=>s.role==='SUBSTITUTE').map(slotHtml).join('')||'<span class="note">替补席：将球员拖到这里，或在球员节点上使用替补按钮。</span>'}</div></div><div class="lineup-actions"><button onclick="saveLineup()">保存阵容</button><button class="secondary" onclick="clearLineup()">清空</button><span class="note">首发 ${lineup.slots.filter(s=>s.role==='STARTER').length}/11 · 替补 ${lineup.slots.filter(s=>s.role==='SUBSTITUTE').length}</span></div></section></div>`;document.querySelector('#formation').onchange=e=>{lineup.formation=e.target.value;const incompatible=lineup.slots.filter(s=>s.role==='STARTER'&&(!zoneByRole(s.tactical_role)||!zoneByRole(s.tactical_role).allow.includes((players.find(p=>p.id===s.player_id)||s).position)));incompatible.forEach(s=>{s.role='SUBSTITUTE';s.tactical_role=null});renderEditor();};}
function zoneHtml(z){const occupied=activeLineup.slots.some(s=>s.role==='STARTER'&&s.tactical_role===z.role);const label=occupied?'':`<span>${z.role}</span><small>${z.allow.join('/')}</small>`;return `<div class="position-zone ${occupied?'occupied':''}" style="left:${z.x*100}%;top:${z.y*100}%" ondragover="event.preventDefault()" ondrop="dropOnZone(event,'${z.role}')">${label}</div>`;}
function slotHtml(s){const p=players.find(x=>x.id===s.player_id)||s;const z=s.role==='STARTER'?zoneByRole(s.tactical_role):null;const style=s.role==='STARTER'&&z?`left:${z.x*100}%;top:${z.y*100}%`:'';return `<div class="slot" style="${style}" draggable="true" ondragstart="dragSlot(event,'${s.player_id}')" oncontextmenu="removePlayer(event,'${s.player_id}')"><div class="circle"></div><span>${escape(lineupName(p))}</span></div>`;}
function addPlayerToState(id){const z=freeZoneFor(id);if(z)activeLineup.slots.push({player_id:id,role:'STARTER',x:z.x,y:z.y,tactical_role:z.role});else activeLineup.slots.push({player_id:id,role:'SUBSTITUTE',x:.5,y:.5,tactical_role:null});}
function addPlayer(id){captureFmDraft();if(activeLineup.slots.some(s=>s.player_id===id))return toast('该球员已在阵容中');addPlayerToState(id);renderEditor();}
function removePlayer(event,id){event.preventDefault();event.stopPropagation();activeLineup.slots=activeLineup.slots.filter(s=>s.player_id!==id);if(activeLineup.captain_id===id)activeLineup.captain_id=null;renderEditor();}
function toggleRole(id){captureFmDraft();const s=activeLineup.slots.find(x=>x.player_id===id);if(s.role==='SUBSTITUTE'){const z=freeZoneFor(id);if(!z)return toast('没有匹配的空位置，请先调整现有首发');s.role='STARTER';s.tactical_role=z.role;s.x=z.x;s.y=z.y;}else{s.role='SUBSTITUTE';s.tactical_role=null;s.x=.5;s.y=.5;}renderEditor();}
function setCaptain(id){captureFmDraft();activeLineup.captain_id=activeLineup.captain_id===id?null:id;renderEditor();}
function dragSlot(e,id){e.dataTransfer.setData('playerId',id)}function dropOnZone(e,role){captureFmDraft();const id=e.dataTransfer.getData('playerId'),s=activeLineup.slots.find(x=>x.player_id===id),z=zoneByRole(role),p=players.find(x=>x.id===id);if(!s||!z||!p)return;if(!z.allow.includes(p.position))return toast(`${p.position} 不能放进 ${role} 位置框`);if(activeLineup.slots.some(x=>x.role==='STARTER'&&x.tactical_role===role&&x.player_id!==id))return toast(`${role} 位置框已被占用，请先移动该球员`);s.role='STARTER';s.tactical_role=role;s.x=z.x;s.y=z.y;activeLineup.selected_player_id=id;renderEditor();}function dropOnBench(e){captureFmDraft();const id=e.dataTransfer.getData('playerId'),s=activeLineup.slots.find(x=>x.player_id===id);if(s){s.role='SUBSTITUTE';s.tactical_role=null;activeLineup.selected_player_id=id;renderEditor();}}
function clearLineup(){if(confirm('清空当前阵容？')){activeLineup.slots=[];activeLineup.captain_id=null;renderEditor();}}
function saveLineup(){activeLineup.name=document.querySelector('#lineup-name').value.trim();activeLineup.notes=document.querySelector('#lineup-notes').value;if(!activeLineup.name)return toast('请输入阵容名称');const body={name:activeLineup.name,formation:activeLineup.formation,season:activeLineup.season,captain_id:activeLineup.captain_id,notes:activeLineup.notes,slots:activeLineup.slots};api(`/lineups${activeLineup.id?'/'+activeLineup.id:''}`,{method:activeLineup.id?'PUT':'POST',body:JSON.stringify(body)}).then(x=>{activeLineup=x;toast('阵容已保存');location.hash='#/lineups/'+x.id}).catch(e=>toast(e.message));}
const fmRoleLibrary={GK:[['守门员',['防守']],['清道夫门将',['支援','进攻']]],CB:[['中后卫',['防守']],['出球中卫',['防守','支援']],['盯人中卫',['防守']]],LB:[['边后卫',['防守','支援']],['进攻型边后卫',['支援','进攻']],['内收边后卫',['防守','支援']]],RB:[['边后卫',['防守','支援']],['进攻型边后卫',['支援','进攻']],['内收边后卫',['防守','支援']]],DM:[['防守型中场',['防守','支援']],['拖后组织核心',['防守','支援']],['抢球中场',['防守','支援']]],CM:[['中场',['防守','支援','进攻']],['全能中场',['支援','进攻']],['组织核心',['支援']],['梅扎拉',['支援','进攻']]],AM:[['前腰',['支援','进攻']],['进攻组织核心',['支援','进攻']],['影子前锋',['进攻']]],LW:[['边锋',['支援','进攻']],['内切边锋',['支援','进攻']],['边路组织者',['支援']]],RW:[['边锋',['支援','进攻']],['内切边锋',['支援','进攻']],['边路组织者',['支援']]],ST:[['中锋',['支援','进攻']],['抢点前锋',['进攻']],['全能前锋',['支援','进攻']],['伪九号',['支援']]]};
function fmRoles(player){return fmRoleLibrary[player?.position]||[['中场',['支援']]]}
function defaultFmRole(player){return fmRoles(player)[0][0]}
function fmSuitability(player,tacticalRole){const zone=zoneByRole(tacticalRole);if(!zone)return {score:'—',label:'替补待定位'};if(player.position==='GK')return zone.allow.includes('GK')?{score:'100%',label:'主位置'}:{score:'不可用',label:'门将仅能守门'};if(!zone.allow.includes(player.position))return {score:'不可用',label:'位置不兼容'};const exact=tacticalRole===player.position||['LCB','CB','RCB'].includes(tacticalRole)&&player.position==='CB'||['LCM','CM','RCM'].includes(tacticalRole)&&player.position==='CM'||['LDM','DM','RDM'].includes(tacticalRole)&&player.position==='DM'||tacticalRole.startsWith('L')&&player.position==='LB'||tacticalRole.startsWith('R')&&player.position==='RB';return exact?{score:'100%',label:'主位置'}:{score:'75%',label:'可用位置'}}
function captureFmDraft(){if(!activeLineup||!document.querySelector('#lineup-name'))return;activeLineup.name=document.querySelector('#lineup-name').value;activeLineup.notes=document.querySelector('#lineup-notes').value;['tactic_style','mentality','attacking_width','pressing'].forEach(key=>{const node=document.querySelector(`#fm-${key}`);if(node)activeLineup[key]=node.value})}
function fmOptions(values,current){return values.map(value=>`<option value="${escape(value)}" ${value===current?'selected':''}>${escape(value)}</option>`).join('')}
function selectLineupPlayer(id){captureFmDraft();activeLineup.selected_player_id=id;renderEditor()}
function setFmRole(value){captureFmDraft();const slot=activeLineup.slots.find(item=>item.player_id===activeLineup.selected_player_id);const player=players.find(item=>item.id===slot?.player_id);if(!slot||!player)return;slot.player_role=value;const duties=(fmRoles(player).find(item=>item[0]===value)||fmRoles(player)[0])[1];if(!duties.includes(slot.duty))slot.duty=duties[0];renderEditor()}
function setFmDuty(value){captureFmDraft();const slot=activeLineup.slots.find(item=>item.player_id===activeLineup.selected_player_id);if(slot){slot.duty=value;renderEditor()}}
function slotHtml(s){const p=players.find(x=>x.id===s.player_id)||s;const z=s.role==='STARTER'?zoneByRole(s.tactical_role):null;const style=s.role==='STARTER'&&z?`left:${z.x*100}%;top:${z.y*100}%`:'';const selected=activeLineup.selected_player_id===s.player_id?' selected':'';return `<div class="slot${selected}" style="${style}" draggable="true" onclick="selectLineupPlayer('${s.player_id}')" ondragstart="dragSlot(event,'${s.player_id}')" oncontextmenu="removePlayer(event,'${s.player_id}')"><div class="circle"></div><span>${escape(lineupName(p))}</span></div>`}
function addPlayerToState(id){const p=players.find(item=>item.id===id),z=freeZoneFor(id);if(!p)return;const slot=z?{player_id:id,role:'STARTER',x:z.x,y:z.y,tactical_role:z.role}:{player_id:id,role:'SUBSTITUTE',x:.5,y:.5,tactical_role:null};slot.player_role=defaultFmRole(p);slot.duty=fmRoles(p)[0][1][0];activeLineup.slots.push(slot);activeLineup.selected_player_id=id}
function removePlayer(event,id){event.preventDefault();event.stopPropagation();captureFmDraft();activeLineup.slots=activeLineup.slots.filter(s=>s.player_id!==id);if(activeLineup.captain_id===id)activeLineup.captain_id=null;if(activeLineup.selected_player_id===id)activeLineup.selected_player_id=null;renderEditor()}
/* Legacy draft retained below while the streamlined tactical-centre renderer is defined after it.
function renderEditor(){captureFmDraft();const lineup=activeLineup;lineup.tactic_style||='均衡';lineup.mentality||='均衡';lineup.attacking_width||='标准';lineup.pressing||='中位';const starters=lineup.slots.filter(s=>s.role==='STARTER'),subs=lineup.slots.filter(s=>s.role==='SUBSTITUTE'),selected=lineup.slots.find(s=>s.player_id===lineup.selected_player_id),selectedPlayer=players.find(p=>p.id===selected?.player_id);const roles=selectedPlayer?fmRoles(selectedPlayer):[];const duties=selectedPlayer?((roles.find(item=>item[0]===(selected.player_role||defaultFmRole(selectedPlayer)))||roles[0])[1]):[];app.innerHTML=`<section class="fm-editor"><div class="fm-toolbar"><div><div class="eyebrow">战术中心</div><h1 class="page-title">${lineup.id?'编辑战术':'新建战术'}</h1></div><div class="fm-toolbar-actions"><label>方案名称<input id="lineup-name" value="${escape(lineup.name)}"></label><label>阵型<select id="formation">${Object.keys(formations).map(f=>`<option ${lineup.formation===f?'selected':''}>${f}</option>`).join('')}</select></label><button onclick="saveLineup()">保存战术</button><a class="button secondary" href="#/lineups">返回</a></div></div><div class="fm-workspace"><aside class="panel fm-squad"><div class="fm-panel-head"><div><span>阵容</span><b>${starters.length}/11 首发</b></div><small>右键移除；已选球员不会留在名单中。</small></div><div class="fm-counts"><span>门将 ${lineup.slots.filter(s=>players.find(p=>p.id===s.player_id)?.position==='GK').length}</span><span>后卫 ${lineup.slots.filter(s=>['CB','LB','RB'].includes(players.find(p=>p.id===s.player_id)?.position)).length}</span><span>中场 ${lineup.slots.filter(s=>['DM','CM','AM'].includes(players.find(p=>p.id===s.player_id)?.position)).length}</span><span>前锋 ${lineup.slots.filter(s=>['LW','RW','ST'].includes(players.find(p=>p.id===s.player_id)?.position)).length}</span></div><div class="pool">${editorPlayers().map(p=>`<div class="pool-player" onclick="addPlayer('${p.id}')"><b>${escape(p.name)}</b><span class="pill">${p.position}</span><div class="sub">${escape(p.club_name||clubs.find(c=>c.id===p.club_id)?.name||'')} · ${p.age||'?'} 岁</div></div>`).join('')}</div></aside><section class="fm-pitch-panel"><div class="fm-pitch-head"><div><b>首发 XI</b><span>${lineup.formation} · ${lineup.mentality}</span></div><span>由下向上进攻</span></div><div class="pitch-wrap"><div id="pitch" class="pitch fm-pitch">${formations[lineup.formation].map(zoneHtml).join('')}${starters.map(slotHtml).join('')}</div><div class="bench" id="bench" ondragover="event.preventDefault()" ondrop="dropOnBench(event)">${subs.map(slotHtml).join('')||'<span class="note">替补席：从球员池加入或将首发拖放至此。</span>'}</div></div><div class="lineup-actions"><button class="secondary" onclick="clearLineup()">清空阵容</button><span class="note">首发 ${starters.length}/11 · 替补 ${subs.length} · 右键球员即可移除</span></div></section><aside class="panel fm-tactics"><div class="fm-panel-head"><div><span>战术指令</span><b>手动设置</b></div><small>不计算适配度或综合评分。</small></div><label>比赛风格<select id="fm-tactic_style">${fmOptions(['均衡','控球','快速反击','高位压迫'],lineup.tactic_style)}</select></label><label>比赛心态<select id="fm-mentality">${fmOptions(['防守','谨慎','均衡','积极','进攻'],lineup.mentality)}</select></label><label>进攻宽度<select id="fm-attacking_width">${fmOptions(['窄','标准','宽'],lineup.attacking_width)}</select></label><label>无球压迫<select id="fm-pressing">${fmOptions(['低位','中位','高位'],lineup.pressing)}</select></label><div class="fm-player-role">${selected&&selectedPlayer?`<div class="fm-selected"><b>${escape(selectedPlayer.name)}</b><span>${selected.role==='STARTER'?'首发':'替补'}${lineup.captain_id===selected.player_id?' · 队长':''}</span></div><label>球员角色<select onchange="setFmRole(this.value)">${fmOptions(roles.map(item=>item[0]),selected.player_role||defaultFmRole(selectedPlayer))}</select></label><label>职责<select onchange="setFmDuty(this.value)">${fmOptions(duties,selected.duty||duties[0])}</select></label><div class="fm-role-actions"><button class="secondary" onclick="toggleRole('${selected.player_id}')">${selected.role==='STARTER'?'移至替补':'进入首发'}</button><button class="secondary" onclick="setCaptain('${selected.player_id}')">${lineup.captain_id===selected.player_id?'取消队长':'设为队长'}</button></div>`:'<div class="note fm-empty-role">点击球场或替补席中的球员，设置其角色与职责。</div>`}</div><label class="fm-notes">战术笔记<textarea id="lineup-notes" rows="5" placeholder="例如：右侧边锋内收，左后卫套边…">${escape(lineup.notes||'')}</textarea></label></aside></div></section>`;document.querySelector('#formation').onchange=e=>{captureFmDraft();lineup.formation=e.target.value;const incompatible=lineup.slots.filter(s=>s.role==='STARTER'&&(!zoneByRole(s.tactical_role)||!zoneByRole(s.tactical_role).allow.includes((players.find(p=>p.id===s.player_id)||s).position)));incompatible.forEach(s=>{s.role='SUBSTITUTE';s.tactical_role=null});renderEditor()};['tactic_style','mentality','attacking_width','pressing'].forEach(key=>document.querySelector(`#fm-${key}`).onchange=()=>captureFmDraft())}
*/
function saveLineup(){captureFmDraft();if(!activeLineup.name.trim())return toast('请输入阵容名称');const body={name:activeLineup.name.trim(),formation:activeLineup.formation,season:activeLineup.season,captain_id:activeLineup.captain_id,notes:activeLineup.notes,tactic_style:activeLineup.tactic_style,mentality:activeLineup.mentality,attacking_width:activeLineup.attacking_width,pressing:activeLineup.pressing,slots:activeLineup.slots};api(`/lineups${activeLineup.id?'/'+activeLineup.id:''}`,{method:activeLineup.id?'PUT':'POST',body:JSON.stringify(body)}).then(x=>{activeLineup=x;toast('战术方案已保存');location.hash='#/lineups/'+x.id}).catch(e=>toast(e.message))}
function fmPoolCards(){return editorPlayers().map(p=>`<div class="pool-player" onclick="addPlayer('${p.id}')"><b>${escape(p.name)}</b><span class="pill">${p.position}</span><div class="sub">${escape(p.club_name||'')} · ${p.age||'?'} 岁</div></div>`).join('')}
function fmFormationOptions(){return Object.keys(formations).map(f=>`<option ${activeLineup.formation===f?'selected':''}>${f}</option>`).join('')}
function fmRolePanel(selected,player){if(!selected||!player)return '<div class="note fm-empty-role">点击球场或替补席中的球员，设置其角色与职责。</div>';const roles=fmRoles(player),current=selected.player_role||defaultFmRole(player),duties=(roles.find(item=>item[0]===current)||roles[0])[1],fit=fmSuitability(player,selected.tactical_role);return `<div class="fm-selected"><b>${escape(player.name)}</b><span>${selected.role==='STARTER'?'首发':'替补'}${activeLineup.captain_id===selected.player_id?' · 队长':''}</span></div><div class="fm-fit"><span>位置适配</span><b>${fit.label}</b><strong>${fit.score}</strong></div><label>球员角色<select onchange="setFmRole(this.value)">${fmOptions(roles.map(item=>item[0]),current)}</select></label><label>职责<select onchange="setFmDuty(this.value)">${fmOptions(duties,selected.duty||duties[0])}</select></label><div class="fm-role-actions"><button class="secondary" onclick="toggleRole('${selected.player_id}')">${selected.role==='STARTER'?'移至替补':'进入首发'}</button><button class="secondary" onclick="setCaptain('${selected.player_id}')">${activeLineup.captain_id===selected.player_id?'取消队长':'设为队长'}</button></div>`}
function renderEditor(){captureFmDraft();const lineup=activeLineup;lineup.tactic_style||='均衡';lineup.mentality||='均衡';lineup.attacking_width||='标准';lineup.pressing||='中位';const starters=lineup.slots.filter(s=>s.role==='STARTER'),subs=lineup.slots.filter(s=>s.role==='SUBSTITUTE'),selected=lineup.slots.find(s=>s.player_id===lineup.selected_player_id),selectedPlayer=players.find(p=>p.id===selected?.player_id);const count=position=>lineup.slots.filter(s=>position.includes(players.find(p=>p.id===s.player_id)?.position)).length;const pitch=formations[lineup.formation].map(zoneHtml).join('')+starters.map(slotHtml).join('');const bench=subs.map(slotHtml).join('')||'<span class="note">替补席：从球员池加入或将首发拖放至此。</span>';app.innerHTML=`<section class="fm-editor"><div class="fm-toolbar"><div><div class="eyebrow">战术中心</div><h1 class="page-title">${lineup.id?'编辑战术':'新建战术'}</h1></div><div class="fm-toolbar-actions"><label>方案名称<input id="lineup-name" value="${escape(lineup.name)}"></label><label>阵型<select id="formation">${fmFormationOptions()}</select></label><button onclick="saveLineup()">保存战术</button><a class="button secondary" href="#/lineups">返回</a></div></div><div class="fm-workspace"><aside class="panel fm-squad"><div class="fm-panel-head"><div><span>阵容</span><b>${starters.length}/11 首发</b></div><small>右键移除；已选球员不会留在名单中。</small></div><div class="fm-counts"><span>门将 ${count(['GK'])}</span><span>后卫 ${count(['CB','LB','RB'])}</span><span>中场 ${count(['DM','CM','AM'])}</span><span>前锋 ${count(['LW','RW','ST'])}</span></div><div class="pool">${fmPoolCards()}</div></aside><section class="fm-pitch-panel"><div class="fm-pitch-head"><div><b>首发 XI</b><span>${lineup.formation} · ${lineup.mentality}</span></div><span>由下向上进攻</span></div><div class="pitch-wrap"><div id="pitch" class="pitch fm-pitch">${pitch}</div><div class="bench" id="bench" ondragover="event.preventDefault()" ondrop="dropOnBench(event)">${bench}</div></div><div class="lineup-actions"><button class="secondary" onclick="clearLineup()">清空阵容</button><span class="note">首发 ${starters.length}/11 · 替补 ${subs.length} · 右键球员即可移除</span></div></section><aside class="panel fm-tactics"><div class="fm-panel-head"><div><span>战术指令</span><b>手动设置</b></div><small>评分来自球探报告，适配度来自位置兼容。</small></div><label>比赛风格<select id="fm-tactic_style">${fmOptions(['均衡','控球','快速反击','高位压迫'],lineup.tactic_style)}</select></label><label>比赛心态<select id="fm-mentality">${fmOptions(['防守','谨慎','均衡','积极','进攻'],lineup.mentality)}</select></label><label>进攻宽度<select id="fm-attacking_width">${fmOptions(['窄','标准','宽'],lineup.attacking_width)}</select></label><label>无球压迫<select id="fm-pressing">${fmOptions(['低位','中位','高位'],lineup.pressing)}</select></label><div class="fm-player-role">${fmRolePanel(selected,selectedPlayer)}</div><label class="fm-notes">战术笔记<textarea id="lineup-notes" rows="5" placeholder="例如：右侧边锋内收，左后卫套边…">${escape(lineup.notes||'')}</textarea></label></aside></div></section>`;document.querySelector('#formation').onchange=e=>{captureFmDraft();lineup.formation=e.target.value;const incompatible=lineup.slots.filter(s=>s.role==='STARTER'&&(!zoneByRole(s.tactical_role)||!zoneByRole(s.tactical_role).allow.includes((players.find(p=>p.id===s.player_id)||s).position)));incompatible.forEach(s=>{s.role='SUBSTITUTE';s.tactical_role=null});renderEditor()};['tactic_style','mentality','attacking_width','pressing'].forEach(key=>document.querySelector(`#fm-${key}`).onchange=()=>captureFmDraft())}
function favoritesPage(){api('/players').then(ps=>{const f=ps.filter(p=>p.favorite);app.innerHTML=`<div class="eyebrow">收藏与报告</div><h1 class="page-title">我的关注清单</h1><p class="muted">收藏球员后可快速返回资料页，继续补充球探报告。</p><section class="section"><div class="grid">${f.length?f.map(playerCard).join(''):`<div class="empty">还没有收藏。去球员详情页点按“收藏”即可建立关注清单。</div>`}</div></section>`;});}
function syncPage(){api('/sync-status').then(data=>{app.innerHTML=`<div class="eyebrow">数据状态</div><h1 class="page-title">当前球员名单</h1><section class="card section"><h2>${data.mode==='provider_ready'?'数据源已就绪':'离线演示模式'}</h2><p class="muted">${escape(data.message)}</p><p class="note">刷新将按数据源的当前赛季名单更新已发现的五大联赛球队；离队球员保留为历史记录，不会显示在当前名单或球员池。</p>${data.mode==='provider_ready'?'<button onclick="runSync()">立即刷新当前名单</button>':'<div class="source">请在 PyCharm 的运行配置中设置环境变量 FOOTBALL_DATA_API_TOKEN 或 API_FOOTBALL_KEY，然后重启服务。密钥不会发送给浏览器。</div>'}</section><section class="section"><h2>刷新记录</h2><div class="card">${data.jobs.map(j=>`<div class="report"><b>${escape(j.provider)}</b> <span class="pill">${j.status}</span><div class="sub">${j.finished_at||'未完成'} · ${j.entity_count||0} 条记录 ${j.error?'· '+escape(j.error):''}</div></div>`).join('')||'<p class="muted">尚未执行刷新。</p>'}</div></section>`;});}
function abilityCards(p){const labels={pace:'速度',shooting:'射门',passing:'传球',dribbling:'盘带',defending:'防守',physical:'身体'};return `<div class="ability-grid">${Object.entries(p.attributes||{}).map(([key,value])=>`<div class="ability"><small>${labels[key]||key}</small><b>${value}</b></div>`).join('')}</div>`}
function playerDetail(id){api(`/players/${id}`).then(p=>{selectedPlayer=p;app.innerHTML=`<a class="link" href="#/players">← 返回球员发现</a><section class="detail-head section"><div class="avatar big">${avatarMedia(p)}</div><div><div class="eyebrow">${escape(p.club_name||'')} · ${escape(p.league||'')}</div><h1>${escape(p.name)}</h1><div class="sub">${posLabel[p.position]||p.position} · ${p.age} 岁 · ${escape(p.nationality||'')}</div></div><div class="overall-card"><small>综合能力</small><b>${p.overall}</b><span>OVR / 100</span></div><div class="actions"><button class="secondary" onclick="toggleFav('${p.id}',${!p.favorite})">${p.favorite?'★ 已收藏':'☆ 收藏'}</button><button onclick="location.hash='#/lineups/new?player=${p.id}'">加入阵容</button></div></section><div class="detail-grid"><div><section class="card"><div class="section-head"><div><h2>能力档案</h2><p>${escape(p.ability_source||'')}</p></div>${p.ability_reference_url?`<a class="link" target="_blank" rel="noreferrer" href="${p.ability_reference_url}">查看官方参考 ↗</a>`:''}</div>${abilityCards(p)}<div class="source">${p.ability_is_reference?'该 OVR 与六项数值来自链接的 EA SPORTS FC 官方公开页面。':'此 OVR 为 ScoutXI 统一基准，方便排序与阵容比较；不是 EA SPORTS FC 官方评分。'}</div></section><section class="card section"><h2>球探观察</h2><div class="stat-row"><div class="stat"><b>${p.appearances}</b><small>出场</small></div><div class="stat"><b>${p.goals}</b><small>进球</small></div><div class="stat"><b>${p.assists}</b><small>助攻</small></div><div class="stat"><b>${p.scout_rating??'—'}</b><small>球探评分</small></div></div><div id="reports">${p.reports.length?p.reports.map(reportHtml).join(''):'<p class="muted">暂无球探报告。</p>'}</div></section></div><aside class="card"><h2>新增球探报告</h2><p class="note">球探报告独立于 OVR 保存，不生成 AI 结论。</p><form id="report-form" class="form-grid"><label>技术<input name="technical" type="number" min="1" max="10" value="7"></label><label>战术<input name="tactical" type="number" min="1" max="10" value="7"></label><label>身体<input name="physical" type="number" min="1" max="10" value="7"></label><label>心理<input name="mental" type="number" min="1" max="10" value="7"></label><label class="wide">优点<input name="strengths" required></label><label class="wide">风险<input name="risks" required></label><label>标签<input name="tags"></label><label>推荐等级<select name="recommendation"><option>重点关注</option><option>持续观察</option><option>不建议</option></select></label><label>观察日期<input name="observed_at" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label class="wide">观察笔记<textarea name="notes" rows="5" required></textarea></label><button class="wide">保存报告</button></form></aside></div>`;document.querySelector('#report-form').onsubmit=e=>saveReport(e,p.id)}).catch(e=>toast(e.message))}
function squadViewPitch(view,roster){if(view.status!=='ready')return `<div class="empty">${escape(view.source)}</div>`;const byId=new Map(roster.map(p=>[p.id,p]));return `<div class="pitch squad-view-pitch">${formations[view.formation]?.map(z=>`<div class="position-zone" style="left:${z.x*100}%;top:${z.y*100}%"><span>${z.role}</span></div>`).join('')||''}${view.slots.map(s=>{const p=byId.get(s.player_id);return p?`<div class="slot" style="left:${s.x*100}%;top:${s.y*100}%"><div class="circle"></div><span>${escape(lineupName(p))}</span></div>`:''}).join('')}</div>`}
function squadQuery(){const selected=new URLSearchParams(location.hash.split('?')[1]||'').get('club')||'';app.innerHTML=`<div class="eyebrow">阵容查询</div><h1 class="page-title">球队阵容与历史首发</h1><p class="muted">查看推荐 XI、赛季出场最多 XI、上一赛季 XI 与上一场首发；每种阵容均标明数据来源。</p><div class="filters"><select id="squad-club"><option value="">选择俱乐部</option>${clubs.map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${escape(c.name)}</option>`).join('')}</select><button id="squad-query-button">查询阵容</button></div><div id="squad-views"></div>`;document.querySelector('#squad-query-button').onclick=()=>{const id=document.querySelector('#squad-club').value;if(!id)return toast('请选择俱乐部');loadSquadViews(id)};if(selected)loadSquadViews(selected)}
function loadSquadViews(id){const outlet=document.querySelector('#squad-views');outlet.innerHTML='<div class="empty">正在加载阵容视图…</div>';api(`/clubs/${id}/squad-views`).then(data=>{const available=data.views.filter(view=>view.status==='ready');outlet.innerHTML=`<section class="section"><div class="section-head"><div><h2>${escape(data.club.name)}</h2><p>${escape(data.season)} · 已显示可用阵容视图</p></div><button class="secondary" onclick="refreshSquadViews('${id}')">同步比赛阵容</button></div><div class="squad-view-tabs">${available.map((view,index)=>`<button class="${index?'secondary':''}" onclick="showSquadView(${data.views.indexOf(view)})">${escape(view.label)}</button>`).join('')}</div><div id="squad-view-body"></div></section>`;window.__squadViews=data;showSquadView(data.views.indexOf(available[0]))}).catch(e=>outlet.innerHTML=`<div class="empty">${escape(e.message)}</div>`)}
function refreshSquadViews(id){const button=event.target;button.disabled=true;button.textContent='同步中…';api(`/clubs/${id}/squad-views/refresh`,{method:'POST'}).then(()=>{toast('已同步可用的比赛阵容');loadSquadViews(id)}).catch(e=>{button.disabled=false;button.textContent='同步比赛阵容';toast(e.message)})}
function showSquadView(index){const data=window.__squadViews,view=data.views[index],outlet=document.querySelector('#squad-view-body');outlet.innerHTML=`<section class="card squad-view-card"><div class="section-head"><div><h2>${escape(view.label)}</h2><p>${escape(view.source)}</p></div><span class="pill">${view.status==='ready'?view.formation:'待同步'}</span></div>${squadViewPitch(view,data.players)}</section>`}
function runSync(){const button=event.target;button.disabled=true;button.textContent='正在刷新…';api('/admin/sync',{method:'POST'}).then(()=>{toast('当前阵容已刷新');loadCore().then(syncPage)}).catch(e=>{button.disabled=false;button.textContent='立即刷新当前名单';toast(e.message)});}
function discover(){const featured=featuredPlayers.slice(0,12),leagues=[...new Set(clubs.map(c=>c.league).filter(Boolean))].sort();app.innerHTML=`<section class="hero"><div class="eyebrow">ScoutXI · 足球球探与阵容管理</div><h1>把观察，变成一套能复用的阵容判断。</h1><p>探索联赛球员库，比较官方 OVR，并创建战术方案。</p><form class="searchbar" onsubmit="event.preventDefault(); location.hash='#/players?search='+encodeURIComponent(this.q.value)"><input name="q" placeholder="搜索球员或俱乐部，例如梅西、C 罗、曼城"><button>开始发现</button></form></section><section class="section"><div class="section-head"><div><h2>近期焦点球员</h2><p>按本赛季进球、助攻排序；仅展示有数据依据的球员。</p></div><a class="link" href="#/players">查看全部 →</a></div><div class="grid">${featured.length?featured.map(featuredPlayerCard).join(''):`<div class="empty">正在等待联赛表现数据刷新。</div>`}</div></section><section class="section"><div class="section-head"><div><h2>热门俱乐部</h2><p>按联赛筛选，再查看球队与阵容。</p></div><select id="popular-league"><option value="">全部联赛</option>${leagues.map(league=>`<option value="${escape(league)}">${escape(league)}</option>`).join('')}</select></div><div id="popular-clubs" class="grid">${clubs.map(club=>`<article class="card club-card" data-league="${escape(club.league)}" onclick="location.hash='#/clubs/${club.id}'">${clubMark(club)}<div class="name">${escape(club.name)}</div><div class="sub">${escape(club.league)} · ${escape(club.country)} · ${club.player_count} 名球员</div></article>`).join('')}</div></section>`;document.querySelector('#popular-league').onchange=e=>document.querySelectorAll('#popular-clubs .club-card').forEach(card=>card.hidden=!!e.target.value&&card.dataset.league!==e.target.value)}
function clubDetail(id){api(`/clubs/${id}`).then(data=>{const c=data.club,time=data.synced_at?data.synced_at.replace('T',' ').replace('Z',' UTC'):'尚未同步';app.innerHTML=`<a class="link" href="#/clubs">← 返回俱乐部</a><section class="detail-head section">${clubMark(c)}<div><div class="eyebrow">${escape(c.country)} · ${escape(c.league)}</div><h1>${escape(c.name)}</h1><div class="sub">${escape(data.season)} 阵容 · ${data.players.length} 名球员</div></div><div class="actions"><button class="secondary" onclick="location.hash='#/squad-query?club=${id}'">查询阵容</button><button onclick="location.hash='#/lineups/new?club=${id}'">用此阵容创建</button></div></section><div class="source section">来源：${escape(data.source)} · 最后同步：${escape(time)}</div><section class="section"><div class="section-head"><div><h2>当前阵容</h2><p>按 OVR 排序；搜索球员姓名或位置。</p></div><input id="club-roster-search" type="search" placeholder="搜索此队球员"></div><div id="club-roster" class="squad">${data.players.sort((a,b)=>b.overall-a.overall).map(p=>`<article class="squad-item" data-search="${escape(`${p.name} ${p.position}`.toLowerCase())}" onclick="location.hash='#/players/${p.id}'"><div class="avatar">${avatarMedia(p)}</div><div><div class="name">${escape(p.name)} <span class="pill">${p.position}</span></div><div class="sub">OVR ${p.overall} · ${p.age||'?'} 岁</div></div></article>`).join('')}</div></section>`;document.querySelector('#club-roster-search').oninput=e=>{const query=e.target.value.trim().toLowerCase();document.querySelectorAll('#club-roster .squad-item').forEach(card=>card.hidden=!!query&&!card.dataset.search.includes(query))}}).catch(e=>toast(e.message))}
function syncPage(){api('/sync-status').then(data=>{app.innerHTML=`<div class="eyebrow">数据状态</div><h1 class="page-title">名单、评分与头像同步</h1><section class="card section"><h2>${data.mode==='provider_ready'?'数据源已就绪':'离线演示模式'}</h2><p class="muted">${escape(data.message)}</p><p class="note">全量名单刷新会在后台遍历五大联赛；EA 官方评分与肖像同步只保存远程链接，不会下载图片到本地。</p>${data.mode==='provider_ready'?'<div class="lineup-actions"><button onclick="runFullRosterSync()">刷新全量名单</button><button class="secondary" onclick="runEaRatingSync()">同步 EA 官方评分与头像</button></div>':'<div class="source">请配置数据源密钥后重启服务。密钥不会发送给浏览器。</div>'}</section><section class="section"><h2>刷新记录</h2><div class="card">${data.jobs.map(j=>`<div class="report"><b>${escape(j.provider)}</b> <span class="pill">${j.status}</span><div class="sub">${j.finished_at||'未完成'} · ${j.entity_count||0} 条记录 ${j.error?'· '+escape(j.error):''}</div></div>`).join('')||'<p class="muted">尚未执行刷新。</p>'}</div></section>`})}
function runFullRosterSync(){const button=event.target;button.disabled=true;button.textContent='已开始后台刷新…';api('/admin/sync-all',{method:'POST'}).then(result=>toast(result.started?'全量名单刷新已在后台启动':'刷新任务已在运行')).catch(e=>{button.disabled=false;button.textContent='刷新全量名单';toast(e.message)})}
function runEaRatingSync(){const button=event.target;button.disabled=true;button.textContent='已开始后台同步…';api('/admin/start-ea-rating-sync',{method:'POST'}).then(result=>toast(result.started?'官方评分与头像同步已在后台启动':'同步任务已在运行')).catch(e=>{button.disabled=false;button.textContent='同步 EA 官方评分与头像';toast(e.message)})}
async function start(){await loadCore();const health=await api('/health');document.querySelector('#data-status').textContent=health.data_mode==='local_demo'?'本地演示数据':'数据已同步';if((location.hash||'').startsWith('#/players?'))playersPage();else nav();}window.addEventListener('hashchange',nav);start();
